    /// ```
    /// # use churchtools_core::*;
    /// # use churchtools_core::queries::*;
    /// # fn main() -> std::result::Result<(), Box<dyn std::error::Error>> {
    /// # let client = churchtools_core::replay::client("get-finance-transactionpurposes-id");
