    /// # use churchtools_core::queries::*;
    /// # fn main() -> std::result::Result<(), Box<dyn std::error::Error>> {
    /// # let client = churchtools_core::replay::client("get-songs");
    /// for song in client.songs().list()? {
    ///     println!("{}", song.name);
    /// }
    /// # Ok(())
    /// # }
    /// ```
